ALTER TABLE agent_activity ADD COLUMN recipient TEXT CHECK(recipient IS NULL OR recipient IN ('INTAKE','EXTRACTOR','RULES_ENGINE','MEMORY','COMMUNICATOR','SAFETY_CHECK','TONE_REVIEWER','OWNER','SUPERVISOR','BRIEFING'));
ALTER TABLE agent_activity ADD COLUMN message_kind TEXT CHECK(message_kind IS NULL OR message_kind IN ('EVIDENCE_PACKET','PAYMENT_CANDIDATES','DECISION','CLIENT_HISTORY','NOTE_DRAFT','REVISION_REQUEST','DRAFT_FOR_APPROVAL','CASE_SELECTION','CASE_OUTCOME','BRIEFING'));
